#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# M3 acceptance: the live claude-p and ralphex adapters on Pro, run by rnship-agent in its
# own GUI session (the LaunchAgent path), with the guard plugin, the init check and pinned
# model IDs. On the fixture app passpier/rnship-s6-probe with a hand-written approved
# baseline, for each adapter:
#   P  a three-task plan (counter → haptics → format) finishes green within one window
#   A  `haptics` adds expo-haptics, which the baseline allowlists: never awaiting_approval
#   G  `share` adds expo-sharing, which it doesn't: ends awaiting_approval on deps.upgrade
#   U  the ledger has usage and the model that ran for every task
# Run as YOUR macOS user, from a rn-ship-pipeline checkout of main, pushed to origin (the
# agent clones the public repo). rnship-agent must be logged in (S0). Results land in
# docs/spikes/M3.results.env (gitignored). No secrets are involved.

ROOT=$(cd "$(dirname "$0")/../.." && pwd)
PIPELINE_URL=https://github.com/passpier/rn-ship-pipeline
AGENT=rnship-agent
AGENT_HOME=/Users/$AGENT
AGENT_RNSHIP=$AGENT_HOME/rnship
AGENT_PATH=$AGENT_RNSHIP/node_modules/.bin:$AGENT_HOME/.local/node/bin:$AGENT_HOME/.local/bin:/usr/bin:/bin:/usr/sbin:/sbin
SHARED=/Users/Shared/rnship-m3   # logs, the fixture bundle, task files, ralphex (1777)
STATE=/Users/Shared/rnship-state # approval records: yours, 755, never writable by the agent
WORK=${RNSHIP_FIXTURE_DIR:-$HOME/Home_Projects/rnship-s6-probe}
RALPHEX_VERSION=1.7.0 # pinned by S8
RALPHEX_TARBALL=ralphex_${RALPHEX_VERSION}_darwin_arm64.tar.gz
RALPHEX_SHA256=c6c437919ffdf624d54fe24cc8fb20ba7c0511f3b44091533a55b72b1b47c6d2
S0_RESULTS=$ROOT/docs/spikes/S0.results.env
ENV_FILE=$ROOT/docs/spikes/M3.results.env
ADAPTERS=(claude-p ralphex)
PLAN_KEYS=(counter haptics format)

trap 'warn "stopped at line $LINENO. Fix the cause and re-run; finished stages are safe to repeat."' ERR

record() { write_env "$1" "$2"; }
fail() { warn "$1"; exit 1; }
s0_value() { sed -n "s/^$1=//p" "$S0_RESULTS" | tail -n1; }
rnship() { node "$ROOT/cli/src/main.ts" "$@"; } # yours, for the baseline approval

# as_agent CMD... runs CMD as rnship-agent, outside its GUI session (no keychain, so no
# Claude): clones, installs, imports, reads. It starts in / because it can't read your cwd.
as_agent() {
  ( cd / && sudo -u "$AGENT" -H /usr/bin/env PATH="$AGENT_PATH" RNSHIP_STATE_DIR="$STATE" "$@" )
}
as_agent_sh() { as_agent /bin/sh -c "cd ~ && $1"; }
db_of() { echo "$AGENT_HOME/.rnship/m3-$1/orchestrator.db"; }
# sql ADAPTER QUERY prints the rows as a JSON array ([] when there are none). Not -readonly:
# after a tick the WAL's -shm is gone, and a read-only connection can't recreate it.
sql() { local out; out=$(as_agent /usr/bin/sqlite3 -json "$(db_of "$1")" "$2"); echo "${out:-[]}"; }
states_of() { sql "$1" "SELECT key, state FROM tasks ORDER BY id" | jq -r 'map("\(.key)=\(.state)") | join(" ")'; }
state_of() { sql "$1" "SELECT state FROM tasks WHERE key = '$2'" | jq -r '.[0].state // "missing"'; }
key_var() { tr 'a-z-' 'A-Z_' <<<"$1" | tr -d '_'; } # claude-p → CLAUDEP

session_up() {
  sudo launchctl print "gui/$AGENT_UID" >/dev/null 2>&1 \
    && sudo test -e "$AGENT_HOME/Library/Keychains/login.keychain-db"
}

# run_in_agent_session LABEL TIMEOUT ADAPTER CMD... runs CMD once as a LaunchAgent in the
# agent's GUI session, where it can use the agent's keychain (Claude OAuth), as the
# production LaunchAgent will. Output goes to $SHARED/LABEL.log. Succeeds if CMD finished
# within TIMEOUT seconds. Every minute it shows the adapter's task states.
run_in_agent_session() {
  local label=$1 timeout=$2 adapter=$3; shift 3
  local job="dev.rnship.m3.$label"
  local plist="$AGENT_HOME/Library/LaunchAgents/$job.plist"
  local log="$SHARED/$label.log" done="$SHARED/$label.done" arg args="" waited=0
  for arg in "$@"; do args+="<string>$arg</string>"; done
  sudo rm -f "$log" "$done"
  sudo launchctl bootout "gui/$AGENT_UID/$job" 2>/dev/null || true
  sudo -u "$AGENT" mkdir -p "$AGENT_HOME/Library/LaunchAgents"
  sudo -u "$AGENT" tee "$plist" >/dev/null <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0"><dict>
  <key>Label</key><string>$job</string>
  <key>ProgramArguments</key><array>
    <string>/bin/sh</string><string>-c</string><string>"\$@"; touch $done</string><string>sh</string>$args
  </array>
  <key>EnvironmentVariables</key><dict>
    <key>PATH</key><string>$AGENT_PATH</string>
  </dict>
  <key>RunAtLoad</key><true/>
  <key>StandardOutPath</key><string>$log</string>
  <key>StandardErrorPath</key><string>$log</string>
</dict></plist>
PLIST
  if sudo launchctl bootstrap "gui/$AGENT_UID" "$plist"; then
    note "running in $AGENT's session (up to $((timeout / 60)) min); log: $log"
    while [[ ! -e "$done" ]] && (( waited < timeout )); do
      sleep 5; waited=$((waited + 5))
      (( waited % 60 == 0 )) && note "$((waited / 60)) min: $(states_of "$adapter" 2>/dev/null || echo '…')"
    done
  else
    warn "bootstrap failed: is $AGENT still logged in (fast user switching)?"
  fi
  sudo launchctl bootout "gui/$AGENT_UID/$job" 2>/dev/null || true
  sudo rm -f "$plist"
  [[ -e "$done" ]]
}

# run_tasks ADAPTER TASKS_YAML KEYS... ticks until every key is done, waiting for you
# (needs_human, awaiting_approval) or parked on quota. At most 6 ticks: a validation retry
# waits in retry_wait for the next one.
run_tasks() {
  local adapter=$1 file=$2 i st settled key; shift 2
  for i in 1 2 3 4 5 6; do
    run_in_agent_session "$adapter-$(basename "$file" .yaml)-$i" 5400 "$adapter" \
      /bin/sh "$SHARED/m3-run.sh" "$adapter" "$file" || fail "the tick didn't finish: see $SHARED"
    tail -n 5 "$SHARED/$adapter-$(basename "$file" .yaml)-$i.log" 2>/dev/null | sed 's/^/    /' || true
    settled=yes
    for key in "$@"; do
      st=$(state_of "$adapter" "$key")
      case "$st" in done|needs_human|awaiting_approval|quota_parked) ;; *) settled=no ;; esac
    done
    [[ $settled == yes ]] && return 0
    note "not settled yet ($(states_of "$adapter")); ticking again in a minute"
    sleep 60
  done
  warn "still not settled after 6 ticks: $(states_of "$adapter")"
}

# check_model_mismatch ADAPTER: the shim refuses a session whose init.model isn't the
# pinned --model. The first live run is where we learn the real init.model string.
check_model_mismatch() {
  local line
  line=$(sql "$1" "SELECT failure_digest FROM tasks WHERE failure_digest LIKE '%model_mismatch%' LIMIT 1" | jq -r '.[0].failure_digest // empty')
  [[ -z "$line" ]] && return 0
  record "M3_$(key_var "$1")_MODEL_MISMATCH" "$(head -n1 <<<"$line" | cut -c1-300)"
  fail "the shim refused the session's model: $line. checkModel's comparison needs fixing before M3 can pass."
}

# report ADAPTER SECONDS records everything the acceptance checks for one adapter.
report() {
  local adapter=$1 secs=$2 p; p="M3_$(key_var "$1")"
  local t1; t1=$(sed -nE 's/^ *T1: *\{ *id: *([a-z0-9-]+).*/\1/p' "$ROOT/policy/routing.yaml")
  record "${p}_PLAN_STATES" "$(sql "$adapter" "SELECT key, state FROM tasks WHERE key IN ('counter','haptics','format') ORDER BY id" | jq -r 'map("\(.key)=\(.state)") | join(",")')"
  record "${p}_PLAN_MINUTES" "$((secs / 60))"
  record "${p}_QUOTA_PARKED" "$(sql "$adapter" "SELECT count(*) AS n FROM events WHERE to_state = 'quota_parked'" | jq -r 'if .[0].n > 0 then "yes" else "no" end')"
  record "${p}_ALLOWLISTED_GATED" "$(sql "$adapter" "SELECT count(*) AS n FROM events e JOIN tasks t ON t.id = e.task_id WHERE t.key = 'haptics' AND e.to_state = 'awaiting_approval'" | jq -r 'if .[0].n > 0 then "yes" else "no" end')"
  record "${p}_GATE_STATE" "$(state_of "$adapter" share)"
  record "${p}_GATE_RULES" "$(sql "$adapter" "SELECT gates FROM tasks WHERE key = 'share'" | jq -r '(.[0].gates // "[]") | fromjson | map("\(.ruleId):\(.matches | join("+"))") | join(",")')"
  local ledger; ledger=$(as_agent /usr/bin/env RNSHIP_DB="$(db_of "$adapter")" rnship ledger)
  record "${p}_USAGE" "$(jq -r 'map("\(.key // "batch")=\(.model_id // "?"):\(.amount)") | join(",")' <<<"$ledger")"
  record "${p}_ROWS_WITHOUT_TASK" "$(jq -r 'map(select(.task_id == null)) | length' <<<"$ledger")"
  record "${p}_MODELS" "$(jq -r 'map(.model_id // "?") | unique | join(",")' <<<"$ledger")"
  record "${p}_MODEL_PINNED" "$(jq -r --arg t1 "$t1" 'if length > 0 and (map(.model_id) | unique) == [$t1] then "yes" else "no" end' <<<"$ledger")"
  record "${p}_NOT_DONE" "$(sql "$adapter" "SELECT key, state, failure_class, substr(replace(coalesce(failure_digest, ''), char(10), ' '), 1, 160) AS digest FROM tasks WHERE state != 'done'" | jq -r 'map("\(.key):\(.state):\(.failure_class // ""):\(.digest)") | join(" | ")')"
}

TOTAL_STAGES=9

banner "M3: live claude-p and ralphex runs as $AGENT"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"
[[ $EUID -ne 0 && "$(id -un)" != "$AGENT" ]] || fail "run this as your own macOS user"
for c in gh jq git node npx curl shasum sudo; do command -v "$c" >/dev/null || fail "missing $c"; done
node -e 'process.exit(+process.versions.node.split(".")[0] >= 24 ? 0 : 1)' || fail "need Node 24 (nvm use 24)"
say "sudo runs every step as $AGENT; enter your password once."
sudo -v
AGENT_UID=$(id -u "$AGENT" 2>/dev/null) || fail "no $AGENT user: run scripts/spikes/s0-identity.sh first"
[[ -f "$S0_RESULTS" && "$(s0_value S0_CLAUDE_P_OK)" == yes ]] || fail "S0 never got claude -p working as $AGENT"
sudo test -x "$AGENT_HOME/.local/bin/claude" || fail "no claude for $AGENT (S0 stage 2)"
[[ "$(as_agent node -v 2>/dev/null)" == v24.* ]] || fail "$AGENT has no Node 24 in ~/.local/node (S0)"
session_up || fail "$AGENT isn't logged in: log in once (user switcher), switch back, re-run"

git -C "$ROOT" fetch -q origin main
[[ -z "$(git -C "$ROOT" status --porcelain)" ]] || fail "uncommitted changes in $ROOT: the agent runs what's on origin/main"
RNSHIP_SHA=$(git -C "$ROOT" rev-parse origin/main)
[[ "$(git -C "$ROOT" rev-parse HEAD)" == "$RNSHIP_SHA" ]] || fail "HEAD isn't origin/main: git push origin main (or pull) first"
[[ -d "$WORK/.git" && -d "$WORK/node_modules" ]] || fail "no fixture checkout with node_modules at $WORK (M1e stage 5)"
mkdir -p "$SHARED" && chmod 1777 "$SHARED"
mkdir -p "$STATE" && chmod 755 "$STATE"
[[ "$(stat -f %Su "$STATE")" == "$(id -un)" ]] || fail "$STATE must be owned by you"
record M3_RNSHIP_SHA "$RNSHIP_SHA"
say "The agent will run rn-ship-pipeline@${RNSHIP_SHA:0:12} on Pro."
note "It makes real claude -p calls: about 8 Sonnet sessions per adapter, in one sitting."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "ralphex v$RALPHEX_VERSION, checksum-pinned"
RALPHEX=$SHARED/bin/ralphex
if [[ -x "$RALPHEX" ]] && "$RALPHEX" --version 2>/dev/null | grep -q "$RALPHEX_VERSION"; then
  say "Already installed: $RALPHEX"
else
  DL=$(mktemp -d)
  curl -fsSL -o "$DL/$RALPHEX_TARBALL" "https://github.com/umputun/ralphex/releases/download/v$RALPHEX_VERSION/$RALPHEX_TARBALL"
  [[ "$(shasum -a 256 "$DL/$RALPHEX_TARBALL" | cut -d' ' -f1)" == "$RALPHEX_SHA256" ]] \
    || fail "the tarball's sha256 doesn't match the pinned one"
  mkdir -p "$DL/x" && tar -xzf "$DL/$RALPHEX_TARBALL" -C "$DL/x" ralphex
  mkdir -p "$SHARED/bin" && chmod 755 "$SHARED/bin"
  install -m 755 "$DL/x/ralphex" "$RALPHEX"
  rm -rf "$DL"
fi
record M3_RALPHEX_VERSION "$("$RALPHEX" --version 2>&1 | head -n1 || true)"
note "$SHARED/bin is yours (755): $AGENT can run ralphex, not replace it."
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "rn-ship-pipeline for $AGENT"
say "$AGENT can't read your checkout, so it clones the public repo at ${RNSHIP_SHA:0:12}."
if sudo test -d "$AGENT_RNSHIP/.git"; then
  as_agent git -C "$AGENT_RNSHIP" fetch -q origin main
else
  as_agent git clone -q "$PIPELINE_URL" "$AGENT_RNSHIP"
fi
as_agent git -C "$AGENT_RNSHIP" checkout -q --detach "$RNSHIP_SHA"
as_agent_sh "cd rnship && npx -y pnpm@10.30.0 install --frozen-lockfile --reporter=silent"
[[ "$(as_agent git -C "$AGENT_RNSHIP" rev-parse HEAD)" == "$RNSHIP_SHA" ]] || fail "the agent's checkout isn't at $RNSHIP_SHA"
as_agent /bin/sh -c 'command -v rnship' >/dev/null || fail "rnship isn't on the agent's PATH"
say "Installed in $AGENT_RNSHIP."
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Hand-written baseline in the fixture app"
cd "$WORK"
git fetch -q origin && git switch -q main && git pull -q --ff-only origin main
HAPTICS=$(node -p 'require("./node_modules/expo/bundledNativeModules.json")["expo-haptics"]')
SHARING=$(node -p 'require("./node_modules/expo/bundledNativeModules.json")["expo-sharing"]')
mkdir -p .rnship
[[ -f .rnship/policy.yaml ]] || printf '# Project policy layer: adds or tightens rules only (ADR 0001). None yet.\nversion: 1\nrules: []\n' > .rnship/policy.yaml
cat > .rnship/validate.sh <<'SH'
#!/bin/sh
# Validation for executor runs. The worktree has no node_modules and the executor may not
# install packages, so this installs what package.json declares (no lockfile writes), then
# type-checks. It lives under .rnship/, so a change to it gates the task.
set -e
npm install --no-audit --no-fund --no-package-lock --loglevel=error
npx --no-install tsc --noEmit
SH
if [[ ! -f .rnship/approved-baseline.yaml ]]; then
  # Draft: every current dependency at its exact spec, expo-haptics allowlisted but unused,
  # and the slice of the resolved Expo config that policy rules watch (from the same
  # loadProjectState `rnship policy check` uses).
  HAPTICS=$HAPTICS node --input-type=module -e '
import { loadProjectState } from "'"$ROOT"'/ota/src/index.ts";
const { config, dependencies } = loadProjectState(".");
const deps = { ...dependencies, "expo-haptics": process.env.HAPTICS };
const pick = (obj, keys) => Object.fromEntries(keys.filter((k) => obj?.[k] !== undefined).map((k) => [k, obj[k]]));
const usage = Object.fromEntries(Object.entries(config.ios?.infoPlist ?? {}).filter(([k]) => /^NS.*UsageDescription$/.test(k)));
const slice = {
  ...(Object.keys(usage).length || config.ios?.privacyManifests ? { ios: { ...(Object.keys(usage).length ? { infoPlist: usage } : {}), ...pick(config.ios, ["privacyManifests"]) } } : {}),
  ...(config.android && (config.android.permissions || config.android.blockedPermissions) ? { android: pick(config.android, ["permissions", "blockedPermissions"]) } : {}),
  ...pick(config, ["plugins"]),
};
const out = [
  "# Approved once, by hand (Stage 0). rnship policy check gates deps and config beyond this.",
  "# expo-haptics is allowlisted but not used yet (M3 acceptance A).",
  "version: 1",
  "dependencies:",
  ...Object.keys(deps).sort().map((k) => `  ${JSON.stringify(k)}: ${JSON.stringify(deps[k])}`),
  `config: ${JSON.stringify(slice, null, 2).split("\n").join("\n  ")}`,
];
process.stdout.write(out.join("\n") + "\n");' > .rnship/approved-baseline.yaml
fi
say "Review the baseline: it's what $AGENT may use without asking you."
step "Dependencies: today's package.json, plus expo-haptics $HAPTICS (allowlisted, unused)."
step "expo-sharing must NOT be in it: acceptance G adds it."
pause "Press Enter to open it in ${EDITOR:-vi}"
"${EDITOR:-vi}" .rnship/approved-baseline.yaml
grep -q '"expo-sharing"' .rnship/approved-baseline.yaml && fail "expo-sharing is in the baseline: remove it, then re-run"
grep -q '"expo-haptics"' .rnship/approved-baseline.yaml || fail "expo-haptics isn't in the baseline: acceptance A needs it"
confirm "Approve this baseline, commit it and push to main? (the push runs the staging OTA workflow)" || fail "stopped; nothing approved"
git add .rnship
git commit -qm "Baseline: hand-written approved baseline and validation for M3" || note "nothing new to commit"
git push -q origin HEAD:main
APPROVE=$(RNSHIP_STATE_DIR=$STATE rnship baseline approve .rnship/approved-baseline.yaml 2>&1) \
  || grep -q 'already approved' <<<"$APPROVE" || fail "baseline approve failed: $APPROVE"
record M3_BASELINE_DIGEST "$(grep -oE '[0-9a-f]{64}' <<<"$APPROVE" | head -n1)"
record M3_FIXTURE_SHA "$(git rev-parse HEAD)"
cd "$ROOT"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Fixture clones for $AGENT"
STALE=""
for a in "${ADAPTERS[@]}"; do
  sudo test -e "$AGENT_HOME/apps/m3-$a" && STALE+=" ~/apps/m3-$a"
  sudo test -e "$AGENT_HOME/.rnship/m3-$a" && STALE+=" ~/.rnship/m3-$a"
done
if [[ -n "$STALE" ]]; then
  say "An earlier M3 run left:$STALE"
  confirm "Delete them and start fresh? (their runs and transcripts go too)" || fail "stopped; move them aside and re-run"
  for a in "${ADAPTERS[@]}"; do as_agent rm -rf "$AGENT_HOME/apps/m3-$a" "$AGENT_HOME/.rnship/m3-$a"; done
fi
BUNDLE=$SHARED/fixture.bundle
rm -f "$BUNDLE" && git -C "$WORK" bundle create "$BUNDLE" main 2>/dev/null && chmod 644 "$BUNDLE"
for a in "${ADAPTERS[@]}"; do
  # One repo per adapter: both DBs number runs from 1, so they'd share agent/run-1.
  as_agent git clone -q -b main "$BUNDLE" "$AGENT_HOME/apps/m3-$a"
  as_agent git -C "$AGENT_HOME/apps/m3-$a" config user.name "$AGENT"
  as_agent git -C "$AGENT_HOME/apps/m3-$a" config user.email "$AGENT@localhost"
  note "npm ci in ~/apps/m3-$a (policy check reads the Expo config from node_modules)…"
  as_agent_sh "cd apps/m3-$a && npm ci --no-audit --no-fund --loglevel=error"
done
# ADR 0002: the settings file and hook rules are yours and only readable by the agent, so a
# session can't loosen the next one. Compiled from your fixture checkout, which is what the
# agent cloned.
mkdir -p "$SHARED/build" && chmod 755 "$SHARED/build"
rnship policy compile "$WORK/.rnship/policy.yaml" --out "$SHARED/build"
chmod 644 "$SHARED"/build/*
as_agent test -r "$SHARED/build/executor-settings.json" || fail "$AGENT can't read $SHARED/build/executor-settings.json"
CHECK=$(as_agent_sh "rnship policy check apps/m3-claude-p --base-ref HEAD" || true)
record M3_BASELINE_APPROVED_FOR_AGENT "$(jq -r '.baseline.approved' <<<"$CHECK")"
record M3_BASELINE_CLEAN_CHECK "$(jq -r 'if .ok then "ok" else (.gates | map(.ruleId) | join(",")) end' <<<"$CHECK")"
[[ "$(jq -r '.baseline.approved' <<<"$CHECK")" == true ]] \
  || fail "the agent doesn't see your baseline approval: $(jq -r '.baseline.reason' <<<"$CHECK")"
note "Wanted: approved true, clean check ok."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Task files and the agent's runner"
VALIDATE='["sh .rnship/validate.sh"]'
cat > "$SHARED/plan.yaml" <<YAML
# M3 acceptance P and A. Chained, so every batch is one task.
version: 1
tasks:
  - id: counter
    title: Add a counter to the home screen
    tier: T1
    files: [src/Counter.tsx, App.tsx]
    validation: $VALIDATE
    body: |
      Create src/Counter.tsx: a component that shows a count starting at 0 and a "+1" button
      (a React Native Pressable) that increments it. Render <Counter /> in App.tsx below the
      existing text.
  - id: haptics
    title: Tap feedback on the counter
    tier: T1
    deps: [counter]
    files: [package.json, src/Counter.tsx]
    validation: $VALIDATE
    body: |
      Add "expo-haptics": "$HAPTICS" to dependencies in package.json by editing the file.
      Don't install anything: validation installs what package.json declares.
      In src/Counter.tsx, call Haptics.selectionAsync() from expo-haptics when "+1" is pressed.
  - id: format
    title: Format the count
    tier: T1
    deps: [haptics]
    files: [src/format.ts, src/Counter.tsx]
    validation: $VALIDATE
    body: |
      Create src/format.ts exporting formatCount(n: number): string, which returns the number
      with thousands separators via toLocaleString("en-US"). Show the count through it in Counter.
YAML
cat > "$SHARED/gate.yaml" <<YAML
# M3 acceptance G: expo-sharing isn't in the approved baseline.
version: 1
tasks:
  - id: share
    title: Share button
    tier: T1
    files: [package.json, src/Counter.tsx]
    validation: $VALIDATE
    body: |
      Add "expo-sharing": "$SHARING" to dependencies in package.json by editing the file.
      Don't install anything: validation installs what package.json declares.
      In src/Counter.tsx, add a "Share" button that calls Sharing.isAvailableAsync() from
      expo-sharing and logs the result with console.log.
YAML
cat > "$SHARED/m3-run.sh" <<RUN
#!/bin/sh
# m3-run.sh ADAPTER TASKS_YAML: one import + tick, as $AGENT in its GUI session.
set -u
adapter=\$1
export PATH="$AGENT_PATH"
export RNSHIP_STATE_DIR="$STATE"
export RNSHIP_DB="\$HOME/.rnship/m3-\$adapter/orchestrator.db"
cd "\$HOME" || exit 1
rnship tasks import "\$2" --app "m3-\$adapter" --flow A --repo "\$HOME/apps/m3-\$adapter" || exit 1
if [ "\$adapter" = ralphex ]; then set -- --ralphex "$SHARED/bin/ralphex"; else set --; fi
rnship tick --executor "\$adapter" --settings "$SHARED/build/executor-settings.json" "\$@"
echo "tick exit=\$?"
RUN
chmod 644 "$SHARED/plan.yaml" "$SHARED/gate.yaml" && chmod 755 "$SHARED/m3-run.sh"
say "Wrote $SHARED/plan.yaml, gate.yaml and m3-run.sh (yours; $AGENT can read, not change)."
note "Tier T1 = $(sed -nE 's/^ *T1: *\{ *id: *([a-z0-9-]+).*/\1/p' "$ROOT/policy/routing.yaml") (policy/routing.yaml)."
pause

# ── 7, 8 ──────────────────────────────────────────────────────────────────
for a in "${ADAPTERS[@]}"; do
  stage "$a: the plan, then the gated task"
  say "Plan: counter → haptics → format. Then share, which must wait for your approval."
  note "Each tick runs in $AGENT's session as a LaunchAgent; you'll see task states every minute."
  START=$(date +%s)
  run_tasks "$a" "$SHARED/plan.yaml" "${PLAN_KEYS[@]}"
  PLAN_SECS=$(( $(date +%s) - START ))
  check_model_mismatch "$a"
  if [[ "$(state_of "$a" format)" == done ]]; then
    run_tasks "$a" "$SHARED/gate.yaml" share
  else
    warn "the plan didn't finish ($(states_of "$a")), so the gated task is skipped"
  fi
  report "$a" "$PLAN_SECS"
  say ""
  grep "^M3_$(key_var "$a")_" "$ENV_FILE" | sed 's/^/    /'
  note "Wanted: plan all done · QUOTA_PARKED no · ALLOWLISTED_GATED no · GATE_STATE awaiting_approval"
  note "· GATE_RULES deps.upgrade:deps:expo-sharing · USAGE has every task · MODEL_PINNED yes."
  pause
done

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Results"
grep '^M3_' "$ENV_FILE" | sed 's/^/    /'
say ""
say "Left in place for inspection (transcripts, worktrees, prompts):"
for a in "${ADAPTERS[@]}"; do step "$AGENT_HOME/.rnship/m3-$a and $AGENT_HOME/apps/m3-$a"; done
note "Clean up later with:"
note "  sudo -u $AGENT rm -rf $AGENT_HOME/.rnship/m3-* $AGENT_HOME/apps/m3-*"
note "The share tasks stay awaiting_approval on purpose; don't approve them."
pause "Press Enter for the summary"

finish
